<?php $pageTitle='Attendance';$summary=['sessions'=>count($allocations),'students'=>0,'present'=>0,'absent'=>0,'unmarked'=>0];foreach($allocations as $item)foreach(['students'=>'student_count','present'=>'present_count','absent'=>'absent_count','unmarked'=>'unmarked_count'] as $key=>$field)$summary[$key]+=(int)$item[$field]; ?>
<div class="ops-page attendance-page ops-enter"><section class="ops-hero"><div><div class="ops-brand"><img src="<?= e(url('assets/images/gbu-emblem.png')) ?>" alt="" width="45" height="45"><span>Gautam Buddha University<br><b>Examination Cell</b></span></div><p class="ops-kicker">Published seating operations</p><h1>Attendance sessions</h1><p>Open room-wise sheets, record presence, and track completion for every published seating plan.</p></div><div class="ops-hero-mark" aria-hidden="true"><span class="ops-icon icon-attendance"></span><strong><?= number_format($summary['unmarked']) ?></strong><small>records awaiting attendance</small></div></section><?php if($success):?><div class="alert success" role="status"><?= e($success) ?></div><?php endif;?>
<section class="ops-metrics" aria-label="Attendance summary"><div><span>Published sessions</span><strong><?= number_format($summary['sessions']) ?></strong><small>Ready for attendance</small></div><div><span>Total students</span><strong><?= number_format($summary['students']) ?></strong><small>Across all sheets</small></div><div><span>Present recorded</span><strong><?= number_format($summary['present']) ?></strong><small><?= $summary['students']?round($summary['present']/$summary['students']*100):0 ?>% of records</small></div><div class="<?= $summary['unmarked']?'attention':'' ?>"><span>Awaiting entry</span><strong><?= number_format($summary['unmarked']) ?></strong><small><?= $summary['unmarked']?'Attendance is incomplete':'All records completed' ?></small></div></section>
<section class="ops-section-head"><div><h2>Session register</h2><p>Open a session to manage its room-wise attendance sheets.</p></div><label class="ops-search"><span class="ops-icon icon-search" aria-hidden="true"></span><input id="attendance-search" type="search" placeholder="Search cycle, date, or shift" aria-label="Search attendance sessions"></label></section>
<?php if($allocations):?><section class="attendance-register" id="attendance-register" aria-live="polite"><?php foreach($allocations as $i=>$a):$total=(int)$a['student_count'];$marked=$total-(int)$a['unmarked_count'];$percent=$total?(int)round($marked/$total*100):0;?><article class="attendance-session" data-search="<?= e(strtolower($a['cycle_name'].' '.date('d M Y',strtotime($a['exam_date'])).' '.$a['shift_name'])) ?>" style="--ops-order:<?= $i ?>"><div class="ops-date"><span><?= e(strtoupper(date('M',strtotime($a['exam_date'])))) ?></span><strong><?= e(date('d',strtotime($a['exam_date']))) ?></strong><small><?= e(date('Y',strtotime($a['exam_date']))) ?></small></div><div class="attendance-session-name"><span><?= e($a['shift_name']) ?></span><h2><?= e($a['cycle_name']) ?></h2><p><b class="ops-icon icon-room" aria-hidden="true"></b><?= (int)$a['room_count'] ?> room sheets</p></div><dl><div><dt>Students</dt><dd><?= number_format($total) ?></dd></div><div><dt>Present</dt><dd><?= number_format((int)$a['present_count']) ?></dd></div><div><dt>Absent</dt><dd><?= number_format((int)$a['absent_count']) ?></dd></div></dl><div class="attendance-progress"><span><b><?= $percent ?>%</b> completed</span><i><b style="--progress:<?= $percent ?>%"></b></i><small><?= number_format((int)$a['unmarked_count']) ?> unmarked</small></div><a href="<?= e(url('attendance/'.$a['id'])) ?>">Open sheets <b aria-hidden="true">→</b></a></article><?php endforeach;?><div class="ops-filter-empty" hidden><strong>No matching sessions</strong><span>Try a different search term.</span></div></section><?php else:?><section class="ops-empty"><span class="ops-icon icon-attendance" aria-hidden="true"></span><h2>No attendance sessions</h2><p>Publish a validated seating allocation to generate attendance sheets automatically.</p><a href="<?= e(url('seating')) ?>">Open seating plans <b aria-hidden="true">→</b></a></section><?php endif;?></div>
<script>(()=>{const input=document.getElementById('attendance-search'),rows=[...document.querySelectorAll('[data-search]')],empty=document.querySelector('.ops-filter-empty');input?.addEventListener('input',()=>{const term=input.value.trim().toLowerCase();let shown=0;rows.forEach(row=>{const visible=row.dataset.search.includes(term);row.hidden=!visible;if(visible)shown++;});if(empty)empty.hidden=shown!==0;});})();</script>
